import { test } from 'node:test';
import assert from 'node:assert/strict';
import { httpEnvironment,releasedHTTP } from './support.js';
test('HTTP upload through mock digitisation, draft, review, fixtures, release and EMR',async t=>{
 const s=await httpEnvironment(t,{shipped:true});const uploaded=await s.ok('/api/guidelines?filename=placeholder.pdf&document_id=PLACEHOLDER-GUIDE',s.bytes);
 assert.equal(uploaded.status,'uploaded');assert.equal((await s.request(`/api/guidelines/${uploaded.sha256}/digitise`,{})).status,409);
 const full=await releasedHTTP(s);assert.equal(full.digitisation.digitiser,'mock-fixture');assert.equal(full.drafts.nodes.length,4);assert.equal(full.release.kind,'release-created');assert.equal((await s.ok('/api/releases')).length,1);
 assert.equal((await s.request('/api/releases',{document_sha256:uploaded.sha256,version:'poc-demo-0.1.0'})).status,409);
 const patient=await s.ok('/api/patients',{name:'PLACEHOLDER e2e',sex:'U'}),path='/api/patients/'+patient.patient_id;
 await s.ok(path+'/diagnoses',{icd10:'B50.9',label:'PLACEHOLDER coded e2e diagnosis',certainty:'confirmed'});await s.ok(path+'/observations',{field:'weight_kg',value:12});const checked=await s.ok(path+'/prescriptions/check',{atc:'P01BF01',tablets:2,release_version:full.release.version});assert.equal(checked.result.advice[0].severity,'warn');assert.equal((await s.ok(`/api/events/${checked.shown.seq}/replay`,{})).matches,true);
});
test('unknown PDF supports complete manual-block path and rejects unparseable release',async t=>{const s=await httpEnvironment(t),bytes=Buffer.from('%PDF-PLACEHOLDER manual-only source');const src=await s.ok('/api/guidelines?filename=manual.pdf&document_id=PLACEHOLDER-MANUAL',bytes);await s.ok(`/api/guidelines/${src.sha256}/metadata`,{edition:'placeholder-manual'});const absent=await s.request(`/api/guidelines/${src.sha256}/digitise`,{});assert.equal(absent.status,404);assert.match(absent.data.error,/manual entry path/);const b={page:1,id:'typed',kind:'table',bbox:[0,0,1,1],text:'PLACEHOLDER hand-typed table',cells:[['Weight','Tablets'],['unknown range','1']]};assert.equal((await s.ok(`/api/guidelines/${src.sha256}/blocks`,b)).digitiser,'manual');assert.equal((await s.ok(`/api/guidelines/${src.sha256}/blocks`)).length,1);const d=await s.ok(`/api/guidelines/${src.sha256}/draft`,{atc_by_block:{typed:'P01BF01'}});assert.ok(d.nodes[0].node.parse_errors.length);const release=await s.request('/api/releases',{document_sha256:src.sha256,version:'poc-demo-0.1.1'});assert.equal(release.status,409);assert.match(release.data.error,/parse errors/);});
